// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// List assets (paginated)
	// (GET /assets)
	ListAssets(ctx context.Context, request ListAssetsRequestObject) (ListAssetsResponseObject, error)
	// Create an asset entity
	// (POST /assets)
	CreateAsset(ctx context.Context, request CreateAssetRequestObject) (CreateAssetResponseObject, error)
	// Soft-delete an asset
	// (DELETE /assets/{id})
	DeleteAsset(ctx context.Context, request DeleteAssetRequestObject) (DeleteAssetResponseObject, error)

	// (GET /assets/{id})
	GetAsset(ctx context.Context, request GetAssetRequestObject) (GetAssetResponseObject, error)

	// (PATCH /assets/{id})
	UpdateAsset(ctx context.Context, request UpdateAssetRequestObject) (UpdateAssetResponseObject, error)
	// All field values for an asset
	// (GET /assets/{id}/fields)
	GetAssetFields(ctx context.Context, request GetAssetFieldsRequestObject) (GetAssetFieldsResponseObject, error)
	// Clear a field value
	// (DELETE /assets/{id}/fields/{field_id})
	ClearAssetFieldValue(ctx context.Context, request ClearAssetFieldValueRequestObject) (ClearAssetFieldValueResponseObject, error)
	// Set or replace a single field value
	// (PUT /assets/{id}/fields/{field_id})
	SetAssetFieldValue(ctx context.Context, request SetAssetFieldValueRequestObject) (SetAssetFieldValueResponseObject, error)
	// Audit trail of changes to one field on one asset
	// (GET /assets/{id}/fields/{field_id}/history)
	GetAssetFieldValueHistory(ctx context.Context, request GetAssetFieldValueHistoryRequestObject) (GetAssetFieldValueHistoryResponseObject, error)
	// Download the asset's primary file (original variant)
	// (GET /assets/{id}/file)
	DownloadAssetFile(ctx context.Context, request DownloadAssetFileRequestObject) (DownloadAssetFileResponseObject, error)
	// Add tags to an asset (bulk, idempotent)
	// (POST /assets/{id}/tags)
	AddAssetTags(ctx context.Context, request AddAssetTagsRequestObject) (AddAssetTagsResponseObject, error)

	// (DELETE /assets/{id}/tags/{tag})
	RemoveAssetTag(ctx context.Context, request RemoveAssetTagRequestObject) (RemoveAssetTagResponseObject, error)
	// Download a named variant of the asset (thumb / preview / etc.)
	// (GET /assets/{id}/variants/{variant})
	DownloadAssetVariant(ctx context.Context, request DownloadAssetVariantRequestObject) (DownloadAssetVariantResponseObject, error)
	// List every capability the server knows about
	// (GET /auth/capabilities)
	ListCapabilities(ctx context.Context, request ListCapabilitiesRequestObject) (ListCapabilitiesResponseObject, error)
	// Sign in with username and password
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// End the current session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Return information about the caller
	// (GET /auth/me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
	// Effective capabilities for the current user
	// (GET /auth/me/capabilities)
	GetMyCapabilities(ctx context.Context, request GetMyCapabilitiesRequestObject) (GetMyCapabilitiesResponseObject, error)
	// Teams the caller is a member of (direct memberships)
	// (GET /auth/me/teams)
	GetMyTeams(ctx context.Context, request GetMyTeamsRequestObject) (GetMyTeamsResponseObject, error)
	// List roles and the capabilities attached to each
	// (GET /auth/roles)
	ListRoles(ctx context.Context, request ListRolesRequestObject) (ListRolesResponseObject, error)
	// List the caller's API tokens
	// (GET /auth/tokens)
	ListApiTokens(ctx context.Context, request ListApiTokensRequestObject) (ListApiTokensResponseObject, error)
	// Issue a new API token
	// (POST /auth/tokens)
	CreateApiToken(ctx context.Context, request CreateApiTokenRequestObject) (CreateApiTokenResponseObject, error)
	// Revoke an API token by ID
	// (DELETE /auth/tokens/{id})
	RevokeApiToken(ctx context.Context, request RevokeApiTokenRequestObject) (RevokeApiTokenResponseObject, error)
	// Assign a role to a user (admin)
	// (PUT /auth/users/{ref}/role)
	SetUserRole(ctx context.Context, request SetUserRoleRequestObject) (SetUserRoleResponseObject, error)
	// List collections (filterable, paginated)
	// (GET /collections)
	ListCollections(ctx context.Context, request ListCollectionsRequestObject) (ListCollectionsResponseObject, error)
	// Create a new collection
	// (POST /collections)
	CreateCollection(ctx context.Context, request CreateCollectionRequestObject) (CreateCollectionResponseObject, error)
	// Hard-delete a collection
	// (DELETE /collections/{id})
	DeleteCollection(ctx context.Context, request DeleteCollectionRequestObject) (DeleteCollectionResponseObject, error)
	// Fetch a single collection by id
	// (GET /collections/{id})
	GetCollection(ctx context.Context, request GetCollectionRequestObject) (GetCollectionResponseObject, error)
	// Partial update of a collection
	// (PATCH /collections/{id})
	UpdateCollection(ctx context.Context, request UpdateCollectionRequestObject) (UpdateCollectionResponseObject, error)
	// List the assets pinned in a collection
	// (GET /collections/{id}/resources)
	ListCollectionResources(ctx context.Context, request ListCollectionResourcesRequestObject) (ListCollectionResourcesResponseObject, error)
	// Add (or re-pin) an asset in a collection
	// (POST /collections/{id}/resources)
	AddCollectionResource(ctx context.Context, request AddCollectionResourceRequestObject) (AddCollectionResourceResponseObject, error)
	// Remove an asset from a collection
	// (DELETE /collections/{id}/resources/{asset_id})
	RemoveCollectionResource(ctx context.Context, request RemoveCollectionResourceRequestObject) (RemoveCollectionResourceResponseObject, error)
	// List field definitions (the metadata schema)
	// (GET /fields)
	ListFields(ctx context.Context, request ListFieldsRequestObject) (ListFieldsResponseObject, error)
	// Create a new field definition (admin)
	// (POST /fields)
	CreateField(ctx context.Context, request CreateFieldRequestObject) (CreateFieldResponseObject, error)
	// Archive (soft-delete) a field definition (admin)
	// (DELETE /fields/{id})
	ArchiveField(ctx context.Context, request ArchiveFieldRequestObject) (ArchiveFieldResponseObject, error)

	// (GET /fields/{id})
	GetField(ctx context.Context, request GetFieldRequestObject) (GetFieldResponseObject, error)
	// Update a field definition (admin)
	// (PATCH /fields/{id})
	UpdateField(ctx context.Context, request UpdateFieldRequestObject) (UpdateFieldResponseObject, error)
	// List posts (paginated feed)
	// (GET /posts)
	ListPosts(ctx context.Context, request ListPostsRequestObject) (ListPostsResponseObject, error)
	// Publish a new post
	// (POST /posts)
	CreatePost(ctx context.Context, request CreatePostRequestObject) (CreatePostResponseObject, error)
	// Soft-delete a post
	// (DELETE /posts/{id})
	DeletePost(ctx context.Context, request DeletePostRequestObject) (DeletePostResponseObject, error)
	// Fetch a post with its members + tags
	// (GET /posts/{id})
	GetPost(ctx context.Context, request GetPostRequestObject) (GetPostResponseObject, error)
	// Partial update of a post
	// (PATCH /posts/{id})
	UpdatePost(ctx context.Context, request UpdatePostRequestObject) (UpdatePostResponseObject, error)
	// Attach an existing asset to a post
	// (POST /posts/{id}/assets)
	AddPostAsset(ctx context.Context, request AddPostAssetRequestObject) (AddPostAssetResponseObject, error)
	// Remove an asset from a post
	// (DELETE /posts/{id}/assets/{asset_id})
	RemovePostAsset(ctx context.Context, request RemovePostAssetRequestObject) (RemovePostAssetResponseObject, error)
	// List all resource types
	// (GET /resource_types)
	ListResourceTypes(ctx context.Context, request ListResourceTypesRequestObject) (ListResourceTypesResponseObject, error)
	// Finalize first-run setup (admin + site + SMTP)
	// (POST /setup/complete)
	CompleteSetup(ctx context.Context, request CompleteSetupRequestObject) (CompleteSetupResponseObject, error)
	// First-run setup status + admin-form prefills
	// (GET /setup/status)
	GetSetupStatus(ctx context.Context, request GetSetupStatusRequestObject) (GetSetupStatusResponseObject, error)
	// Upload a raw byte stream
	// (POST /storage/objects)
	UploadStorageObject(ctx context.Context, request UploadStorageObjectRequestObject) (UploadStorageObjectResponseObject, error)
	// Download a raw byte stream by content hash (original variant)
	// (GET /storage/objects/{hash})
	DownloadStorageObject(ctx context.Context, request DownloadStorageObjectRequestObject) (DownloadStorageObjectResponseObject, error)
	// Download a specific variant of a stored object
	// (GET /storage/objects/{hash}/variants/{variant})
	DownloadStorageObjectVariant(ctx context.Context, request DownloadStorageObjectVariantRequestObject) (DownloadStorageObjectVariantResponseObject, error)
	// List teams (paginated; optional ancestor filter)
	// (GET /teams)
	ListTeams(ctx context.Context, request ListTeamsRequestObject) (ListTeamsResponseObject, error)
	// Create a team
	// (POST /teams)
	CreateTeam(ctx context.Context, request CreateTeamRequestObject) (CreateTeamResponseObject, error)
	// Soft-delete a team
	// (DELETE /teams/{id})
	DeleteTeam(ctx context.Context, request DeleteTeamRequestObject) (DeleteTeamResponseObject, error)
	// Fetch a team with its direct parents
	// (GET /teams/{id})
	GetTeam(ctx context.Context, request GetTeamRequestObject) (GetTeamResponseObject, error)
	// Rename or re-describe a team
	// (PATCH /teams/{id})
	UpdateTeam(ctx context.Context, request UpdateTeamRequestObject) (UpdateTeamResponseObject, error)
	// List a team's members
	// (GET /teams/{id}/members)
	ListTeamMembers(ctx context.Context, request ListTeamMembersRequestObject) (ListTeamMembersResponseObject, error)
	// Add a user to a team
	// (POST /teams/{id}/members)
	AddTeamMember(ctx context.Context, request AddTeamMemberRequestObject) (AddTeamMemberResponseObject, error)
	// Remove a user from a team
	// (DELETE /teams/{id}/members/{rs_user_id})
	RemoveTeamMember(ctx context.Context, request RemoveTeamMemberRequestObject) (RemoveTeamMemberResponseObject, error)
	// List the team's direct parents
	// (GET /teams/{id}/parents)
	ListTeamParents(ctx context.Context, request ListTeamParentsRequestObject) (ListTeamParentsResponseObject, error)
	// Add a parent edge (creates a DAG link)
	// (POST /teams/{id}/parents)
	AddTeamParent(ctx context.Context, request AddTeamParentRequestObject) (AddTeamParentResponseObject, error)
	// Sever a parent edge
	// (DELETE /teams/{id}/parents/{parent_id})
	RemoveTeamParent(ctx context.Context, request RemoveTeamParentRequestObject) (RemoveTeamParentResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

